    if damaged and requested_days <= damaged_deadline:
        amount = float(item.get("price", 0)) + float(item.get("shipping", 0))
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if item.get("final_sale", False):
        return {"action": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0.0}

    window_map = policy["return_window_days"]
    if category not in window_map:
        return {"action": "decline", "amount_usd": 0.0}

    window_days = int(window_map[category])
