    refund_end = standard_end
    if holiday and holiday_end > refund_end:
        refund_end = holiday_end

    amount = float(item.get("price", 0))
    accessory_deduction = missing_value(item, ret.get("missing_accessories", []))

    if requested_days <= refund_end:
        fee = 0.0
        if category == "electronics" and opened:
            if not (holiday and requested_days <= holiday_end):
