    holidayEligible = (
        deliveredMonth == 11 and deliveredDay >= 15
    ) or deliveredMonth == 12
    holidayEligible = holidayEligible and requestedDays <= holidayDeadline

    missingValue = 0.0
    accessoryNames = set(missing)
    for accessory in item["accessories"]:
        if accessory["name"] in accessoryNames:
            missingValue += float(accessory["value"])

    fee = 0.0
    if opened and category == "electronics" and not holidayEligible:
        fee = price * float(policy["restocking_fee_opened_electronics"])

    amount = price - fee - missingValue
    if amount < 0:
        amount = 0.0

    daysSinceDelivery = requestedDays - deliveredDays

    if holidayEligible:
