def refund_decision(api, return_id: str) -> dict:
    return_record = api.read_return(return_id)
    order_record = api.read_order(return_record["order_id"])
    customer_record = api.read_customer(order_record["customer_id"])
    policy = api.read_policy()

    sku = return_record["sku"]
    item = None
    for candidate in order_record["items"]:
        if candidate["sku"] == sku:
            item = candidate
            break

    if item is None:
        return {"action": "decline", "amount_usd": 0.0}

    def parse_date(date_text):
        parts = date_text.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def days_from_civil(year, month, day):
        if month <= 2:
            year -= 1
            month += 12
        return 365 * year + year // 4 - year // 100 + year // 400 + (153 * month - 457) // 5 + day - 306

    def date_to_days(date_text):
        year, month, day = parse_date(date_text)
        return days_from_civil(year, month, day)

    delivered_year, delivered_month, delivered_day = parse_date(order_record["delivered_on"])
    requested_days = date_to_days(return_record["requested_on"])
    delivered_days = days_from_civil(delivered_year, delivered_month, delivered_day)

    if requested_days < delivered_days:
        return {"action": "decline", "amount_usd": 0.0}

    reason = return_record["reason"].lower()
    damaged = ("damag" in reason) or ("broken" in reason) or ("defect" in reason)

    item_price = float(item["price"])
    shipping = float(item["shipping"])
    category = item["category"]
    final_sale = bool(item["final_sale"])
    opened = bool(return_record["opened"])

    if damaged:
        if requested_days - delivered_days <= 90:
            return {"action": "refund", "amount_usd": round(item_price + shipping, 2)}

    if final_sale:
        return {"action": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0.0}

    window_days = policy.get("return_window_days", {}).get(category)
    if window_days is None:
        return {"action": "decline", "amount_usd": 0.0}

    tier = customer_record.get("tier", "")
    extra_days = 0
    if isinstance(tier, str) and tier.lower() == "plus":
        extra_days = int(policy.get("member_extra_days", 0))

    window_end_days = delivered_days + int(window_days) + extra_days
    credit_end_days = window_end_days + int(policy.get("store_credit_days_after_window", 0))

    delivered_holiday = False
    if (delivered_month == 11 and delivered_day >= 15) or (delivered_month == 12):
        delivered_holiday = True

    holiday_end_days = days_from_civil(delivered_year + 1, 1, 31)
    holiday_active = delivered_holiday and requested_days <= holiday_end_days

    missing_total = 0.0
    missing_accessories = return_record.get("missing_accessories", [])
    accessories = item.get("accessories", [])
    for missing_name in missing_accessories:
        for accessory in accessories:
            if accessory.get("name") == missing_name:
                missing_total += float(accessory.get("value", 0.0))

    fee = 0.0
    if category == "electronics" and opened and not holiday_active:
        fee = item_price * float(policy.get("restocking_fee_opened_electronics", 0.0))

    amount = item_price - missing_total - fee
    if amount < 0:
        amount = 0.0

    if holiday_active:
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if requested_days <= window_end_days:
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if requested_days <= credit_end_days:
        return {"action": "credit", "amount_usd": round(amount, 2)}

    return {"action": "decline", "amount_usd": 0.0}
