def refund_decision(api, return_id: str) -> dict:
    def leap_year(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def date_to_ordinal(date_text):
        parts = date_text.split("-")
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])

        days = 0
        for y in range(1, year):
            days += 365
            if leap_year(y):
                days += 1

        month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        for m in range(1, month):
            days += month_lengths[m - 1]
            if m == 2 and leap_year(year):
                days += 1

        days += day
        return days

    def date_parts(date_text):
        parts = date_text.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    policy = api.read_policy()
    customer = api.read_customer(order["customer_id"])

    item = None
    for candidate in order["items"]:
        if candidate["sku"] == ret["sku"]:
            item = candidate
            break

    if item is None:
        return {"action": "decline", "amount_usd": 0.0}

    requested_ord = date_to_ordinal(ret["requested_on"])
    delivered_ord = date_to_ordinal(order["delivered_on"])

    if requested_ord < delivered_ord:
        return {"action": "decline", "amount_usd": 0.0}

    reason_text = str(ret.get("reason", "")).lower()
    damaged = "damag" in reason_text

    if damaged:
        damaged_days = policy.get("damaged_refund_days", 90)
        if requested_ord - delivered_ord <= damaged_days:
            amount = float(item["price"]) + float(item["shipping"])
            return {"action": "refund", "amount_usd": round(max(0.0, amount), 2)}

    if item.get("final_sale", False):
        return {"action": "decline", "amount_usd": 0.0}

    category = item.get("category")
    window_days_by_category = policy.get("return_window_days", {})
    if category not in window_days_by_category:
        return {"action": "decline", "amount_usd": 0.0}

    window_days = int(window_days_by_category[category])
    extra_days = 0
    tier = str(customer.get("tier", "")).lower()
    if "plus" in tier:
        extra_days = int(policy.get("member_extra_days", 0))

    normal_card_deadline = delivered_ord + window_days + extra_days

    delivered_year, delivered_month, delivered_day = date_parts(order["delivered_on"])
    holiday = False
    holiday_card_deadline = normal_card_deadline
    if (delivered_month == 11 and delivered_day >= 15) or delivered_month == 12:
        holiday = True
        holiday_card_deadline = date_to_ordinal(str(delivered_year + 1) + "-01-31")

    if holiday and holiday_card_deadline > normal_card_deadline:
        card_deadline = holiday_card_deadline
    else:
        card_deadline = normal_card_deadline

    credit_deadline = card_deadline + int(policy.get("store_credit_days_after_window", 30))

    opened = bool(ret.get("opened", False))
    if opened and category == "beauty":
        return {"action": "decline", "amount_usd": 0.0}

    missing_names = set(ret.get("missing_accessories", []))
    missing_value = 0.0
    for accessory in item.get("accessories", []):
        if accessory.get("name") in missing_names:
            missing_value += float(accessory.get("value", 0.0))

    restocking_fee = 0.0
    if opened and category == "electronics" and not holiday:
        restocking_fee = float(policy.get("restocking_fee_opened_electronics", 0.0)) * float(item["price"])

    amount = float(item["price"]) - missing_value - restocking_fee
    amount = max(0.0, amount)

    if requested_ord <= card_deadline:
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if requested_ord <= credit_deadline:
        return {"action": "credit", "amount_usd": round(amount, 2)}

    return {"action": "decline", "amount_usd": 0.0}
