def refund_decision(api, return_id: str) -> dict:
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def to_ordinal(date_text):
        year = int(date_text[0:4])
        month = int(date_text[5:7])
        day = int(date_text[8:10])
        days_before_month = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        days = 365 * (year - 1) + (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
        days += days_before_month[month - 1] + day
        if month > 2 and is_leap(year):
            days += 1
        return days

    def pad_year(year):
        text = str(year)
        while len(text) < 4:
            text = "0" + text
        return text

    def find_item(order_data, sku):
        for item in order_data.get("items", []):
            if item.get("sku") == sku:
                return item
        return None

    def missing_value(item_data, missing_list):
        accessories = item_data.get("accessories", []) or []
        missing_names = []
        if isinstance(missing_list, list):
            for entry in missing_list:
                if isinstance(entry, dict):
                    name = entry.get("name", "")
                else:
                    name = str(entry)
                missing_names.append(str(name).lower())
        elif missing_list:
            missing_names.append(str(missing_list).lower())

        used = [False] * len(accessories)
        total = 0.0
        for miss in missing_names:
            for i, accessory in enumerate(accessories):
                if not used[i]:
                    acc_name = str(accessory.get("name", "")).lower()
                    if acc_name == miss:
                        total += float(accessory.get("value", 0))
                        used[i] = True
                        break
        return total

    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    policy = api.read_policy()
    customer = api.read_customer(order["customer_id"])

    item = find_item(order, ret.get("sku"))
    if item is None:
        return {"action": "decline", "amount_usd": 0}

    delivered_on = order.get("delivered_on", "")
    requested_on = ret.get("requested_on", "")
    delivered_ord = to_ordinal(delivered_on)
    requested_ord = to_ordinal(requested_on)

    if requested_ord < delivered_ord:
        return {"action": "decline", "amount_usd": 0}

    category = item.get("category", "")
    window_days = policy.get("return_window_days", {}).get(category)
    if window_days is None:
        return {"action": "decline", "amount_usd": 0}

    tier = str(customer.get("tier", "")).lower()
    effective_window = int(window_days) + (int(policy.get("member_extra_days", 0)) if tier == "plus" else 0)
    credit_days = int(policy.get("store_credit_days_after_window", 0))

    year = int(delivered_on[0:4])
    holiday_start = to_ordinal(pad_year(year) + "-11-15")
    holiday_end = to_ordinal(pad_year(year) + "-12-31")
    holiday_limit = to_ordinal(pad_year(year + 1) + "-01-31")
    holiday_return = delivered_ord >= holiday_start and delivered_ord <= holiday_end and requested_ord <= holiday_limit

    reason_text = str(ret.get("reason", "")).lower()
    damaged = (
        ("damag" in reason_text or "broken" in reason_text or "defect" in reason_text)
        and requested_ord - delivered_ord <= int(policy.get("damaged_refund_days", 0))
    )

    price = float(item.get("price", 0))
    shipping = float(item.get("shipping", 0))
    opened = bool(ret.get("opened", False))
    final_sale = bool(item.get("final_sale", False))
    missing_amount = missing_value(item, ret.get("missing_accessories", []))

    if damaged:
        amount = round(price + shipping, 2)
        return {"action": "refund", "amount_usd": amount}

    if final_sale:
        return {"action": "decline", "amount_usd": 0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0}

    if holiday_return:
        amount = price - missing_amount
        if amount < 0:
            amount = 0.0
        return {"action": "refund", "amount_usd": round(amount, 2)}

    fee = 0.0
    if category == "electronics" and opened:
        fee = price * float(policy.get("restocking_fee_opened_electronics", 0))

    base_amount = price - fee - missing_amount
    if base_amount < 0:
        base_amount = 0.0

    if requested_ord <= delivered_ord + effective_window:
        return {"action": "refund", "amount_usd": round(base_amount, 2)}

    if requested_ord <= delivered_ord + effective_window + credit_days:
        return {"action": "credit", "amount_usd": round(base_amount, 2)}

    return {"action": "decline", "amount_usd": 0}
