def refund_decision(api, return_id: str) -> dict:
    def dateToDays(text):
        parts = str(text).split("-")
        y = int(parts[0])
        m = int(parts[1])
        d = int(parts[2])
        if m <= 2:
            y = y - 1
            m = m + 12
        era = y // 400
        yoe = y - era * 400
        doy = (153 * (m - 3) + 2) // 5 + d - 1
        doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
        return era * 146097 + doe

    def cleanText(value):
        return str(value).strip().lower()

    def findItem(items, sku):
        for item in items:
            if cleanText(item.get("sku", "")) == cleanText(sku):
                return item
        return None

    def textCandidates(value):
        out = []
        if isinstance(value, dict):
            keys = ["name", "sku", "id", "accessory", "description", "title"]
            for key in keys:
                if key in value and value[key] is not None:
                    out.append(cleanText(value[key]))
        else:
            out.append(cleanText(value))
        return out

    def accessoryValue(accessory):
        if isinstance(accessory, dict):
            keys = ["price", "value", "amount", "amount_usd", "cost"]
            for key in keys:
                if key in accessory and accessory[key] is not None:
                    val = accessory[key]
                    if isinstance(val, int) or isinstance(val, float):
                        return float(val)
                    if isinstance(val, str):
                        try:
                            return float(val)
                        except Exception:
                            pass
        elif isinstance(accessory, int) or isinstance(accessory, float):
            return float(accessory)
        elif isinstance(accessory, str):
            try:
                return float(accessory)
            except Exception:
                pass
        return 0.0

    def accessoryMissing(accessory, missingSet):
        candidates = textCandidates(accessory)
        for cand in candidates:
            for miss in missingSet:
                if cand == miss or cand in miss or miss in cand:
                    return True
        return False

    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    customer = api.read_customer(order["customer_id"])
    policy = api.read_policy()

    sku = ret.get("sku", "")
    item = findItem(order.get("items", []), sku)
    if item is None:
        return {"action": "decline", "amount_usd": 0.0}

    reason = cleanText(ret.get("reason", ""))
    opened = bool(ret.get("opened", False))
    missingAccessories = ret.get("missing_accessories", [])
    requestedOn = ret.get("requested_on", "")
    deliveredOn = order.get("delivered_on", "")

    daysSinceDelivery = dateToDays(requestedOn) - dateToDays(deliveredOn)
    if daysSinceDelivery < 0:
        return {"action": "decline", "amount_usd": 0.0}

    price = float(item.get("price", 0.0))
    shipping = float(item.get("shipping", 0.0))
    category = cleanText(item.get("category", ""))
    tier = cleanText(customer.get("tier", ""))

    if "damage" in reason and daysSinceDelivery <= int(policy.get("damaged_refund_days", 0)):
        return {"action": "refund", "amount_usd": round(price + shipping, 2)}

    windowMap = policy.get("return_window_days", {})
    windowDays = int(windowMap.get(category, 0))
    if tier == "plus":
        windowDays = windowDays + int(policy.get("member_extra_days", 0))

    if item.get("final_sale", False):
        return {"action": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0.0}

    amount = price

    if category == "electronics" and opened:
        amount = amount - price * float(policy.get("restocking_fee_opened_electronics", 0.0))

    missingSet = set()
    for miss in missingAccessories:
        for cand in textCandidates(miss):
            missingSet.add(cand)

    for accessory in item.get("accessories", []):
        if accessoryMissing(accessory, missingSet):
            amount = amount - accessoryValue(accessory)

    if amount < 0:
        amount = 0.0

    if daysSinceDelivery <= windowDays:
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if daysSinceDelivery <= windowDays + int(policy.get("store_credit_days_after_window", 0)):
        return {"action": "credit", "amount_usd": round(amount, 2)}

    return {"action": "decline", "amount_usd": 0.0}
