            total += 1
        return total

    def norm_name(value):
        return str(value).lower()

    def accessory_name(value):
        if isinstance(value, dict):
            if "name" in value:
                return norm_name(value["name"])
            if "sku" in value:
                return norm_name(value["sku"])
            if "id" in value:
                return norm_name(value["id"])
        return norm_name(value)

    def accessory_value(value):
        if isinstance(value, dict):
            if "price" in value:
                return float(value["price"])
            if "value" in value:
                return float(value["value"])
            if "amount" in value:
                return float(value["amount"])
        return 0.0

    reason = norm_name(ret.get("reason", ""))
    delivered_days = days_from_date(order["delivered_on"])
    requested_days = days_from_date(ret["requested_on"])
    days_after_delivery = requested_days - delivered_days

    damaged_days = policy["damaged_refund_days"]
    if "damaged" in reason and days_after_delivery <= damaged_days:
        amount = float(item.get("price", 0.0)) + float(item.get("shipping", 0.0))
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if item.get("final_sale"):
        return {"action": "decline", "amount_usd": 0.0}

    category = norm_name(item.get("category", ""))
    windows = policy["return_window_days"]
    window_days = int(windows.get(category, 0))

    tier = norm_name(customer.get("tier", ""))
    if tier == "plus":
        window_days += int(policy["member_extra_days"])

    opened = bool(ret.get("opened"))
    if opened and category == "beauty":
        return {"action": "decline", "amount_usd": 0.0}

    amount = float(item.get("price", 0.0))

    missing = ret.get("missing_accessories", [])
    missing_names = set()
    for entry in missing:
        missing_names.add(accessory_name(entry))

    accessories = item.get("accessories", [])
    for acc in accessories:
        if accessory_name(acc) in missing_names:
            amount -= accessory_value(acc)

    if opened and category == "electronics":
        amount -= float(item.get("price", 0.0)) * float(policy["restocking_fee_opened_electronics"])

    amount = max(0.0, amount)

    if days_after_delivery <= window_days:
        return {"action": "refund", "amount_usd": round(amount, 2)}

    if days_after_delivery <= window_days + int(policy["store_credit_days_after_window"]):
        return {"action": "credit", "amount_usd": round(amount, 2)}

    return {"action": "decline", "amount_usd": 0.0}
