        return int(parts[0]), int(parts[1]), int(parts[2])

    def is_leap(year):
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        return year % 4 == 0

    def month_offset(year, month):
        offsets = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        total = offsets[month - 1]
        if month > 2 and is_leap(year):
            total += 1
        return total

    def to_ordinal(text):
        year, month, day = date_parts(text)
        leap_days = (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
        return (year - 1) * 365 + leap_days + month_offset(year, month) + day

    def is_damaged(reason_text):
        text = str(reason_text).strip().lower()
        return ("damag" in text) or ("broken" in text) or ("defect" in text) or ("fault" in text)

