    if holiday_end_ord is not None and requested_ord <= holiday_end_ord:
        action = "refund"
    elif requested_ord <= window_end:
        action = "refund"
    elif requested_ord <= credit_end:
        action = "credit"

    if action == "decline":
        return {"action": "decline", "amount_usd": 0.0}

    amount = float(item.get("price", 0))

    waived_fee = False
    if holiday_end_ord is not None and requested_ord <= holiday_end_ord:
