    damaged = False
    for word in ["damaged", "broken", "defective", "faulty", "arrived damaged"]:
        if word in reason:
            damaged = True
            break

    delivered = order["delivered_on"]
    requested = ret["requested_on"]
    del_year, del_month, del_day = parts(delivered)
    req_serial = serial(requested)

