            return {"action": "refund", "amount_usd": round(price + shipping, 2)}

    if item.get("final_sale", False):
        return {"action": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0.0}

    missing = set()
    for name in ret["missing_accessories"]:
        missing.add(str(name).lower())

    missing_value = 0.0
    for accessory in item.get("accessories", []):
        if str(accessory["name"]).lower() in missing:
            missing_value += float(accessory["value"])

    holiday = False
    if (del_month == 11 and del_day >= 15) or del_month == 12:
        holiday = True

    if holiday:
        cutoff = serial(str(del_year + 1) + "-01-31")
        if req_serial <= cutoff:
            amount = price - missing_value
            if amount < 0:
                amount = 0.0
            return {"action": "refund", "amount_usd": round(amount, 2)}

    window = 0
    if category in policy["return_window_days"]:
        window = int(policy["return_window_days"][category])

    if tier == "plus":
        window += int(policy["member_extra_days"])

    end = serial(delivered) + window
    credit_end = end + int(policy["store_credit_days_after_window"])

    amount = price
    if opened and category == "electronics":
        amount -= price * float(policy["restocking_fee_opened_electronics"])
    amount -= missing_value
    if amount < 0:
        amount = 0.0

    if req_serial <= end:
        return {"action": "refund", "amount_usd": round(amount, 2)}
    if req_serial <= credit_end:
        return {"action": "credit", "amount_usd": round(amount, 2)}
    return {"action": "decline", "amount_usd": 0.0}
