    def parts(text):
        return int(text[0:4]), int(text[5:7]), int(text[8:10])

    def toord(y, m, d):
        a = (14 - m) // 12
        y2 = y + 4800 - a
        m2 = m + 12 * a - 3
        return d + (153 * m2 + 2) // 5 + 365 * y2 + y2 // 4 - y2 // 100 + y2 // 400 - 32045

    def diff(a, b):
        y1, m1, d1 = parts(a)
        y2, m2, d2 = parts(b)
        return toord(y1, m1, d1) - toord(y2, m2, d2)

    def damaged(reason):
        text = str(reason).lower()
        for word in ["damaged", "broken", "defective"]:
            if word in text:
                return True
        return False

    delivered = str(ordr["delivered_on"])
    requested = str(ret["requested_on"])
