    reason = str(ret.get("reason", "")).lower()
    opened = bool(ret.get("opened", False))
    missing = ret.get("missing_accessories", [])
    finalsale = bool(item.get("final_sale", False))

    requestdays = diff(requested, delivered)

    if damaged(reason) and requestdays >= 0 and requestdays <= int(pol.get("damaged_refund_days", 90)):
        return {"action": "refund", "amount_usd": round(price + shipping, 2)}

    if finalsale:
        return {"action": "decline", "amount_usd": 0.0}

    ydel, mdel, ddel = parts(delivered)
    yreq, mreq, dreq = parts(requested)

    holiday = False
    if (mdel == 11 and ddel >= 15) or (mdel == 12):
        if requestdays >= 0 and toord(yreq, mreq, dreq) <= toord(ydel + 1, 1, 31):
            holiday = True

    if category == "beauty" and opened and not holiday:
        return {"action": "decline", "amount_usd": 0.0}

    window = int(pol.get("return_window_days", {}).get(category, 0))
    if "plus" in tier:
        window += int(pol.get("member_extra_days", 0))

    if holiday:
        action = "refund"
    else:
        if requestdays <= window:
            action = "refund"
        elif requestdays <= window + int(pol.get("store_credit_days_after_window", 0)):
            action = "credit"
        else:
            return {"action": "decline", "amount_usd": 0.0}

    amount = price

    if opened and category == "electronics" and not holiday:
        amount -= price * float(pol.get("restocking_fee_opened_electronics", 0))

    accessories = item.get("accessories", [])
    for miss in missing:
        missname = str(miss).lower()
        for acc in accessories:
            if str(acc.get("name", "")).lower() == missname:
                amount -= float(acc.get("value", 0))
                break

    if amount < 0:
        amount = 0.0

    return {"action": action, "amount_usd": round(amount, 2)}
