def refund_decision(api, return_id: str) -> dict:
    r = api.read_return(return_id)
    o = api.read_order(r["order_id"])
    c = api.read_customer(o["customer_id"])
    p = api.read_policy()

    sku = r.get("sku", "")
    item = None
    for it in o.get("items", []):
        if it.get("sku", "") == sku:
            item = it
            break
    if item is None and len(o.get("items", [])) > 0:
        item = o.get("items", [])[0]

    def parse_date(s):
        parts = str(s).split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def leap_year(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def ordinal(y, m, d):
        month_days = [31, 28 + (1 if leap_year(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        before = 0
        i = 1
        while i < y:
            before += 365 + (1 if leap_year(i) else 0)
            i += 1
        j = 1
        while j < m:
            before += month_days[j - 1]
            j += 1
        return before + d

    def lower_text(x):
        return str(x).strip().lower()

    def is_plus_member(tier):
        t = lower_text(tier)
        return t == "plus" or "plus" in t

    def missing_accessory_value(it, missing_list):
        missing = set()
        for x in missing_list:
            missing.add(lower_text(x))
        total = 0.0
        for acc in it.get("accessories", []):
            name = lower_text(acc.get("name", ""))
            if name in missing:
                total += float(acc.get("value", 0.0))
        return total

    def damaged_reason(reason):
        text = lower_text(reason)
        return ("damag" in text) or ("broken" in text) or ("defect" in text)

    delivered_y, delivered_m, delivered_d = parse_date(o.get("delivered_on", "1970-01-01"))
    requested_y, requested_m, requested_d = parse_date(r.get("requested_on", "1970-01-01"))
    delivered_ord = ordinal(delivered_y, delivered_m, delivered_d)
    requested_ord = ordinal(requested_y, requested_m, requested_d)
    days_since_delivery = requested_ord - delivered_ord

    category = lower_text(item.get("category", ""))
    price = float(item.get("price", 0.0))
    shipping = float(item.get("shipping", 0.0))
    opened = bool(r.get("opened", False))
    final_sale = bool(item.get("final_sale", False))
    reason = r.get("reason", "")
    missing_value = missing_accessory_value(item, r.get("missing_accessories", []))

    windows = p.get("return_window_days", {})
    base_window = int(windows.get(category, 0))
    extra_days = int(p.get("member_extra_days", 0)) if is_plus_member(c.get("tier", "")) else 0
    refund_window = base_window + extra_days
    credit_window = refund_window + int(p.get("store_credit_days_after_window", 0)) + extra_days

    holiday = False
    if (delivered_m == 11 and delivered_d >= 15) or (delivered_m == 12):
        next_year = delivered_y + 1
        if requested_ord <= ordinal(next_year, 1, 31):
            holiday = True

    if damaged_reason(reason) and days_since_delivery <= int(p.get("damaged_refund_days", 0)):
        amount = round(max(0.0, price + shipping), 2)
        return {"action": "refund", "amount_usd": amount}

    if final_sale:
        return {"action": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"action": "decline", "amount_usd": 0.0}

    if holiday:
        amount = price - missing_value
        amount = round(max(0.0, amount), 2)
        return {"action": "refund", "amount_usd": amount}

    fee = 0.0
    if category == "electronics" and opened:
        fee = float(p.get("restocking_fee_opened_electronics", 0.0)) * price

    amount = price - fee - missing_value
    amount = round(max(0.0, amount), 2)

    if days_since_delivery <= refund_window:
        return {"action": "refund", "amount_usd": amount}

