        def date_parts(date_text):
            parts = str(date_text).split("-")
            return int(parts[0]), int(parts[1]), int(parts[2])

        def ordinal(date_text):
            year, month, day = date_parts(date_text)
            leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
            month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            total = 365 * (year - 1) + (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
            i = 1
            while i < month:
                total += month_days[i - 1]
                if i == 2 and leap:
                    total += 1
                i += 1
            total += day
            return total

        def find_order_item(order_items, sku):
            i = 0
            while i < len(order_items):
                item = order_items[i]
                if item.get("sku") == sku:
                    return item
                i += 1
            return None

        def accessory_rows(accessories):
            rows = []
            if not isinstance(accessories, list):
                return rows
            i = 0
            while i < len(accessories):
                acc = accessories[i]
                name = ""
                value = 0.0
                if isinstance(acc, dict):
                    if "name" in acc:
                        name = str(acc["name"])
                    elif "title" in acc:
                        name = str(acc["title"])
                    elif "label" in acc:
                        name = str(acc["label"])
                    elif "description" in acc:
                        name = str(acc["description"])
                    elif "sku" in acc:
                        name = str(acc["sku"])
                    keys = ["price", "value", "amount", "cost", "price_usd", "value_usd", "amount_usd", "cost_usd"]
                    j = 0
                    while j < len(keys):
                        key = keys[j]
                        if key in acc:
                            try:
                                value = float(acc[key])
                            except Exception:
                                value = 0.0
                            break
                        j += 1
                elif isinstance(acc, (list, tuple)):
                    if len(acc) > 0:
                        name = str(acc[0])
                    if len(acc) > 1:
                        try:
                            value = float(acc[1])
                        except Exception:
                            value = 0.0
                else:
                    name = str(acc)
                rows.append([name.strip().lower(), value, False])
                i += 1
            return rows

        def missing_accessory_deduction(accessories, missing_list):
            rows = accessory_rows(accessories)
            total = 0.0
            if missing_list is None:
                return total
            if not isinstance(missing_list, list):
                missing_list = [missing_list]
            i = 0
            while i < len(missing_list):
                target = str(missing_list[i]).strip().lower()
                j = 0
                while j < len(rows):
                    if not rows[j][2] and rows[j][0] == target:
                        total += rows[j][1]
                        rows[j][2] = True
                        break
                    j += 1
                i += 1
            return total

        item = find_order_item(order_data.get("items", []), return_data.get("sku"))
