        if delivered_on is None or requested_on is None:
            return {"method": "decline", "amount_usd": 0.0}

        delivered_ordinal = ordinal(delivered_on)
        requested_ordinal = ordinal(requested_on)
        if requested_ordinal < delivered_ordinal:
            return {"method": "decline", "amount_usd": 0.0}

        days_since_delivery = requested_ordinal - delivered_ordinal

        reason_text = str(return_data.get("reason", "")).lower()
