        price = float(item.get("price", 0.0))
        shipping = float(item.get("shipping", 0.0))
        category = str(item.get("category", "")).strip().lower()
        final_sale = bool(item.get("final_sale"))

        customer_tier = str(customer_data.get("tier", "")).strip().lower()
        extra_days = 15 if customer_tier == "plus" else 0

        window_map = policy.get("return_window_days", {})
        base_window = window_map.get(category)
        if base_window is None:
            total_window = -1
        else:
            total_window = int(base_window) + extra_days

        restocking_fee = float(policy.get("restocking_fee_opened_electronics", 0.0))
        damaged_days = int(policy.get("damaged_refund_days", 90))
        store_credit_days = int(policy.get("store_credit_days_after_window", 0))

        delivery_year, delivery_month, delivery_day = date_parts(delivered_on)
        holiday_delivery = (delivery_month == 11 and delivery_day >= 15) or (delivery_month == 12)
        holiday_deadline = ordinal(str(delivery_year + 1) + "-01-31")
        holiday_active = holiday_delivery and requested_ordinal <= holiday_deadline

        if damaged and days_since_delivery <= damaged_days:
            amount = round(price + shipping, 2)
            return {"method": "card", "amount_usd": amount}

        if final_sale:
            return {"method": "decline", "amount_usd": 0.0}

        if opened and category == "beauty":
            return {"method": "decline", "amount_usd": 0.0}

        deduction = missing_accessory_deduction(item.get("accessories", []), missing_accessories)

        if holiday_active:
            amount = price - deduction
            if amount < 0:
                amount = 0.0
            return {"method": "card", "amount_usd": round(amount, 2)}

        if days_since_delivery <= total_window:
            amount = price
            if opened and category == "electronics":
                amount -= price * restocking_fee
            amount -= deduction
            if amount < 0:
                amount = 0.0
            return {"method": "card", "amount_usd": round(amount, 2)}

        if days_since_delivery <= total_window + store_credit_days:
            amount = price
            if opened and category == "electronics":
                amount -= price * restocking_fee
            amount -= deduction
            if amount < 0:
                amount = 0.0
            return {"method": "store_credit", "amount_usd": round(amount, 2)}

        return {"method": "decline", "amount_usd": 0.0}
    except Exception:
        return {"method": "decline", "amount_usd": 0.0}
