    accessory_loss = 0.0
    accessories = item.get("accessories", [])
    if not isinstance(accessories, list):
        accessories = []
    for acc in accessories:
        if acc.get("name") in missing_names:
            accessory_loss += float(acc.get("value", 0))

    y, m, d = ymd(delivered_on)
    holiday = (m == 11 and d >= 15) or (m == 12)
    if holiday:
        cutoff = daynum(str(y + 1) + "-01-31")
        if requested_num <= cutoff:
            amount = price - accessory_loss
            if amount < 0:
                amount = 0.0
            return {"method": "card", "amount_usd": round(amount, 2)}

    window_days = int(policy.get("return_window_days", {}).get(category, 0))
    if customer.get("tier") == "plus":
        window_days += int(policy.get("member_extra_days", 0))

    credit_days = int(policy.get("store_credit_days_after_window", 0))
    if days_since_delivery < 0:
        return {"method": "decline", "amount_usd": 0.0}

    if days_since_delivery <= window_days:
        method = "card"
    elif days_since_delivery <= window_days + credit_days:
        method = "store_credit"
    else:
        return {"method": "decline", "amount_usd": 0.0}

    amount = price - accessory_loss
    if category == "electronics" and opened:
        amount -= price * float(policy.get("restocking_fee_opened_electronics", 0))

    if amount < 0:
        amount = 0.0

    return {"method": method, "amount_usd": round(amount, 2)}
