def refund_decision(api, return_id: str) -> dict:
    def parse_date(date_text):
        parts = date_text.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def date_ord(date_text):
        year, month, day = parse_date(date_text)
        days = 365 * (year - 1)
        days += (year - 1) // 4
        days -= (year - 1) // 100
        days += (year - 1) // 400
        month_days = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        days += month_days[month - 1]
        days += day
        if month > 2 and is_leap(year):
            days += 1
        return days

    def is_holiday_delivery(delivery_text):
        year, month, day = parse_date(delivery_text)
        return (month == 11 and day >= 15) or (month == 12)

    def holiday_deadline_ord(delivery_text):
        year, month, day = parse_date(delivery_text)
        if (month == 11 and day >= 15) or (month == 12):
            return date_ord(str(year + 1) + "-01-31")
        return 0

    def money_to_amount(value):
        if value < 0:
            value = 0.0
        cents = int(value * 100 + 0.5)
        return cents / 100.0

    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    customer = api.read_customer(order["customer_id"])
    policy = api.read_policy()

    sku = ret.get("sku")
    items = order.get("items", [])
    item = None
    for candidate in items:
        if candidate.get("sku") == sku:
            item = candidate
            break

    if item is None:
        return {"method": "decline", "amount_usd": 0.0}

    requested_on = ret.get("requested_on")
    delivered_on = order.get("delivered_on")

    req_ord = date_ord(requested_on)
    deliv_ord = date_ord(delivered_on)

    if req_ord < deliv_ord:
        return {"method": "decline", "amount_usd": 0.0}

    reason = str(ret.get("reason", "")).lower()
    damaged = "damag" in reason

    opened = bool(ret.get("opened"))
    missing = ret.get("missing_accessories", [])
    if not isinstance(missing, list):
        missing = []

    category = str(item.get("category", "")).lower()
    price = float(item.get("price", 0))
    shipping = float(item.get("shipping", 0))
    final_sale = bool(item.get("final_sale"))

    tier = str(customer.get("tier", "")).lower()
    extra_days = 0
    if tier == "plus":
        extra_days = int(policy.get("member_extra_days", 0))

    window_map = policy.get("return_window_days", {})
    window_days = int(window_map.get(category, 0)) + extra_days
    close_ord = deliv_ord + window_days
    credit_end_ord = close_ord + int(policy.get("store_credit_days_after_window", 0))

    damage_days = int(policy.get("damaged_refund_days", 0))
    damaged_ok = damaged and req_ord <= deliv_ord + damage_days

    accessories = item.get("accessories", [])
    accessory_deduction = 0.0
    if isinstance(accessories, list) and len(missing) > 0:
        for missing_name in missing:
            missing_text = str(missing_name).lower()
            for accessory in accessories:
                if str(accessory.get("name", "")).lower() == missing_text:
                    accessory_deduction += float(accessory.get("value", 0))
                    break

    if damaged_ok:
        amount = price + shipping
        return {"method": "card", "amount_usd": money_to_amount(amount)}

    if final_sale:
        return {"method": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"method": "decline", "amount_usd": 0.0}

    holiday = is_holiday_delivery(delivered_on)
    holiday_deadline = holiday_deadline_ord(delivered_on)

    fee = 0.0
    if category == "electronics" and opened:
        fee = price * float(policy.get("restocking_fee_opened_electronics", 0))

    if holiday and req_ord <= holiday_deadline:
        amount = price - accessory_deduction
        return {"method": "card", "amount_usd": money_to_amount(amount)}

    if req_ord <= close_ord:
        amount = price - fee - accessory_deduction
        return {"method": "card", "amount_usd": money_to_amount(amount)}

    if req_ord <= credit_end_ord:
        amount = price - fee - accessory_deduction
        return {"method": "store_credit", "amount_usd": money_to_amount(amount)}

    return {"method": "decline", "amount_usd": 0.0}
