def refund_decision(api, return_id):
    def parseDate(text):
        year = int(text[0:4])
        month = int(text[5:7])
        day = int(text[8:10])
        return year, month, day

    def leapYear(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def ordinal(text):
        year, month, day = parseDate(text)
        monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = day
        index = 1
        while index < month:
            total += monthDays[index - 1]
            index += 1
        if month > 2 and leapYear(year):
            total += 1
        yearBefore = year - 1
        total += 365 * yearBefore + yearBefore // 4 - yearBefore // 100 + yearBefore // 400
        return total

    def accessoryDeduction(item, missing):
        accessories = item.get("accessories", [])
        if not isinstance(accessories, list):
            accessories = []
        if not isinstance(missing, list):
            missing = []
        total = 0.0
        seen = set()
        for entry in missing:
            if isinstance(entry, dict):
                name = str(entry.get("name", ""))
            else:
                name = str(entry)
            if name in seen:
                continue
            seen.add(name)
            for accessory in accessories:
                if isinstance(accessory, dict) and str(accessory.get("name", "")) == name:
                    total += float(accessory.get("value", 0))
                    break
        return total

    declineResult = {"method": "decline", "amount_usd": 0.0}

    try:
        returnInfo = api.read_return(return_id)
        orderInfo = api.read_order(returnInfo["order_id"])
        customerInfo = api.read_customer(orderInfo["customer_id"])
        policyInfo = api.read_policy()
    except Exception:
        return declineResult

    if not isinstance(returnInfo, dict) or not isinstance(orderInfo, dict) or not isinstance(customerInfo, dict) or not isinstance(policyInfo, dict):
        return declineResult
    if "error" in returnInfo or "error" in orderInfo or "error" in customerInfo or "error" in policyInfo:
        return declineResult

    item = None
    sku = returnInfo.get("sku")
    items = orderInfo.get("items", [])
    if isinstance(items, list):
        for entry in items:
            if isinstance(entry, dict) and entry.get("sku") == sku:
                item = entry
                break
    if item is None:
        return declineResult

    requestedOn = str(returnInfo.get("requested_on", ""))
    deliveredOn = str(orderInfo.get("delivered_on", ""))
    if not requestedOn or not deliveredOn:
        return declineResult

    reason = str(returnInfo.get("reason", "")).lower()

    if "damag" in reason and ordinal(requestedOn) <= ordinal(deliveredOn) + 90:
        amount = float(item.get("price", 0)) + float(item.get("shipping", 0))
        return {"method": "card", "amount_usd": round(amount, 2)}

    if bool(item.get("final_sale")):
        return declineResult

    if bool(returnInfo.get("opened")) and str(item.get("category", "")).lower() == "beauty":
        return declineResult

    deliveredYear, deliveredMonth, deliveredDay = parseDate(deliveredOn)
    holiday = deliveredMonth == 12 or (deliveredMonth == 11 and deliveredDay >= 15)
    if holiday and ordinal(requestedOn) <= ordinal(str(deliveredYear + 1) + "-01-31"):
        amount = float(item.get("price", 0))
        amount -= accessoryDeduction(item, returnInfo.get("missing_accessories", []))
        if amount < 0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    category = str(item.get("category", ""))
    windowDaysByCategory = policyInfo.get("return_window_days", {})
    if not isinstance(windowDaysByCategory, dict) or category not in windowDaysByCategory:
        return declineResult

    windowDays = int(windowDaysByCategory.get(category, 0))
    customerTier = str(customerInfo.get("tier", "")).lower()
    if customerTier == "plus":
        windowDays += int(policyInfo.get("member_extra_days", 0))

    requestOrd = ordinal(requestedOn)
    deliveredOrd = ordinal(deliveredOn)
    if requestOrd <= deliveredOrd + windowDays:
        method = "card"
    elif requestOrd <= deliveredOrd + windowDays + int(policyInfo.get("store_credit_days_after_window", 0)):
        method = "store_credit"
    else:
        return declineResult

    amount = float(item.get("price", 0))
    amount -= accessoryDeduction(item, returnInfo.get("missing_accessories", []))
    if bool(returnInfo.get("opened")) and str(item.get("category", "")).lower() == "electronics":
        amount -= float(item.get("price", 0)) * float(policyInfo.get("restocking_fee_opened_electronics", 0))
    if amount < 0:
        amount = 0.0
    return {"method": method, "amount_usd": round(amount, 2)}
